  static String money(double n){if(!Double.isFinite(n))return "—";return NumberFormat.getCurrencyInstance(Locale.US).format(n);}
  static String shortMoney(double n){if(n>=1e12)return String.format(Locale.US,"$%.2fT",n/1e12);if(n>=1e9)return String.format(Locale.US,"$%.2fB",n/1e9);if(n>=1e6)return String.format(Locale.US,"$%.2fM",n/1e6);return money(n);}
  static String pct(double n){return String.format(Locale.US,"%+.2f%%",n);}
  static String val(BigDecimal n){return money(n.doubleValue());}
  public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getCrossPlatformLookAndFeelClassName());}catch(Exception ignored){}new Studio().setVisible(true);});}

